CREATE TABLE demo_stock (id INTEGER PRIMARY KEY, qty INTEGER NOT NULL CHECK(qty>=0));
INSERT INTO demo_stock VALUES (1,10),(2,20);
SELECT id,qty FROM demo_stock ORDER BY qty DESC;

CREATE TABLE sample_stock (id INTEGER PRIMARY KEY, sku VARCHAR(30) NOT NULL UNIQUE);
INSERT INTO sample_stock VALUES (1,'MASK-1');
ALTER TABLE sample_stock ADD COLUMN label VARCHAR(80);
ALTER TABLE sample_stock ADD COLUMN status VARCHAR(30) DEFAULT '未分类';
SELECT id,label,status FROM sample_stock ORDER BY sku;

CREATE TABLE demo_parent (id INTEGER PRIMARY KEY);
CREATE TABLE demo_child (id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL REFERENCES demo_parent(id));
INSERT INTO demo_parent VALUES (1),(2);
INSERT INTO demo_child VALUES (1,1),(2,1);
SELECT p.id,COUNT(c.id) AS children FROM demo_parent p LEFT JOIN demo_child c ON p.id=c.parent_id GROUP BY p.id ORDER BY children DESC;

CREATE TABLE discard_stock(id INTEGER PRIMARY KEY);
DROP TABLE discard_stock;
